          background: currentTheme.sider.background,
          borderRight: `1px solid ${currentTheme.sider.borderColor}`,
          boxShadow: '0 2px 8px rgba(0, 0, 0, 0.05)',
          display: 'flex',
          flexDirection: 'column',
        }}
      >
        <div
          style={{
            height: 64,
            fontSize: 18,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            fontWeight: 600,
            color: currentTheme.sider.logoColor,
            background: currentTheme.sider.background,
          }}
        >
          <img
            src={icon}
            alt="icon"
            style={{ width: 40, height: 40, marginRight: 12 }}
          />
          <span>资产管理平台</span>
        </div>
        <Menu
          mode="inline"
          selectedKeys={selectedKeys}
          items={items}
          onClick={(e) => history.push(e.key)}
          className="sidebar-menu"
          style={{
            borderRight: 0,
            fontSize: 14,
            fontWeight: 400,
            flex: 1,
            paddingTop: 16,
            background: currentTheme.sider.background,
          }}
          theme={theme}
          selectable
        />
        <div
          style={{
            padding: '20px 24px',
            borderBottom: `1px solid ${currentTheme.sider.borderColor}`,
            background: currentTheme.sider.background,
          }}
        >
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: '12px',
              cursor: 'pointer',
              padding: '8px',
              borderRadius: '8px',
              transition: 'all 0.3s ease',
            }}
            onClick={() => history.push('/profile')}
            onMouseEnter={(e) => {
              e.currentTarget.style.background =
                theme === 'light' ? '#f5f7fa' : '#2D3748';
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.background = 'transparent';
            }}
          >
            <div
              style={{
                width: 40,
                height: 40,
                borderRadius: '50%',
                backgroundColor: '#4f54bd',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                color: '#ffffff',
                fontWeight: 600,
                fontSize: 16,
                flexShrink: 0,
              }}
            >
              {localStorage.getItem('loginUser')?.charAt(0).toUpperCase() ||
                'A'}
            </div>
            <div
              style={{
                flex: 1,
              }}
            >
              <div
                style={{
                  fontSize: 14,
                  fontWeight: 500,
                  color: currentTheme.text.primary,
                  marginBottom: 2,
                }}
              >
                管理员
              </div>
              <div
                style={{
                  fontSize: 12,
                  fontWeight: 400,
                  color: currentTheme.text.tertiary,
                }}
