            padding: '0 32px',
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
            borderBottom: `1px solid ${currentTheme.header.borderColor}`,
            boxShadow: '0 1px 4px rgba(0, 0, 0, 0.04)',
