            <Breadcrumb
              items={breadcrumbItems}
              style={{
                fontSize: 14,
                fontWeight: 500,
              }}
              separator={
                <span style={{ color: currentTheme.header.breadcrumbColor }}>
                  /
                </span>
              }
              itemRender={(route, params, routes) => {
                const isLast = routes.indexOf(route) === routes.length - 1;
                return (
                  <span
                    style={{
                      color: isLast
                        ? currentTheme.header.breadcrumbColor
                        : currentTheme.header.breadcrumbColor,
                      cursor: isLast ? 'default' : 'pointer',
                      transition: 'color 0.3s',
                    }}
                    onClick={(e) => {
                      if (!isLast && route.href) {
                        e.preventDefault();
                        history.push(route.href);
                      }
                    }}
                  >
                    {route.title}
                  </span>
                );
              }}
            />
          </div>
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: 12,
            }}
          >
            <Button
              type="text"
              icon={theme === 'light' ? <SunFilled /> : <MoonFilled />}
              onClick={toggleTheme}
              style={{
                width: 40,
                height: 40,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                borderRadius: 8,
                color: currentTheme.header.textColor,
                transition: 'all 0.3s ease',
              }}
              onMouseEnter={(e) => {
                e.currentTarget.style.background =
                  theme === 'light' ? '#f5f7fa' : '#2D3748';
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.background = 'transparent';
              }}
            />
            <div
              style={{
                display: 'flex',
                alignItems: 'center',
                gap: 12,
                padding: '6px 12px',
                borderRadius: 12,
                border: `1px solid ${currentTheme.header.borderColor}`,
                backgroundColor: currentTheme.header.userCardBg,
                transition: 'all 0.3s ease',
              }}
            >
              <div
                style={{
                  width: 36,
                  height: 36,
                  borderRadius: '50%',
                  background:
                    'linear-gradient(135deg, #4f54bd 0%, #6366f1 100%)',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  color: '#ffffff',
                  fontWeight: 600,
                  fontSize: 15,
                  cursor: 'pointer',
                  boxShadow: '0 2px 8px rgba(79, 84, 189, 0.3)',
                  transition: 'all 0.3s ease',
                }}
                onMouseEnter={(e) => {
                  e.currentTarget.style.transform = 'translateY(-1px)';
                  e.currentTarget.style.boxShadow =
                    '0 4px 12px rgba(79, 84, 189, 0.4)';
                }}
                onMouseLeave={(e) => {
                  e.currentTarget.style.transform = 'translateY(0)';
                  e.currentTarget.style.boxShadow =
                    '0 2px 8px rgba(79, 84, 189, 0.3)';
                }}
              >
                {localStorage.getItem('loginUser')?.charAt(0).toUpperCase() ||
                  'U'}
              </div>
              <div
                style={{
                  display: 'flex',
                  flexDirection: 'column',
                  gap: 2,
                }}
              >
                <div
                  style={{
                    fontSize: 14,
                    fontWeight: 500,
                    color: currentTheme.header.textColor,
                    lineHeight: 1.2,
                  }}
                >
                  {localStorage.getItem('loginUser') || '用户'}
                </div>
                <div
                  style={{
                    fontSize: 12,
                    fontWeight: 400,
                    color: theme === 'light' ? '#A0AEC0' : '#718096',
                    lineHeight: 1.2,
                  }}
                >
                  管理员
                </div>
              </div>
            </div>
            <Button
              type="text"
              icon={<LogoutOutlined />}
              onClick={() => {
                localStorage.removeItem('loginUser');
                history.push('/login');
              }}
              style={{
                display: 'flex',
                alignItems: 'center',
                gap: 6,
                padding: '8px 16px',
                height: 36,
                borderRadius: 8,
                fontWeight: 500,
                fontSize: 14,
                color: currentTheme.header.textColor,
                transition: 'all 0.3s ease',
              }}
              onMouseEnter={(e) => {
                if (theme === 'light') {
                  e.currentTarget.style.background = '#fee2e2';
                  e.currentTarget.style.color = '#dc2626';
                } else {
                  e.currentTarget.style.background = '#7f1d1d';
                  e.currentTarget.style.color = '#fca5a5';
                }
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.background = 'transparent';
                e.currentTarget.style.color = currentTheme.header.textColor;
              }}
            >
              退出登录
            </Button>
          </div>
        </Header>
        <Content
          style={{
            backgroundColor: currentTheme.content.background,
            minHeight: 280,
            maxHeight: 'calc(100vh - 64px)',
            overflowY: 'auto',
          }}
        >
          <Outlet />
        </Content>
      </Layout>
    </Layout>
  );
}

