`;

export default function Devices() {
  const actionRef = useRef<any>();
  const [createVisible, setCreateVisible] = useState(false);
  const [editVisible, setEditVisible] = useState(false);
  const [deleteVisible, setDeleteVisible] = useState(false);
  const [createForm] = Form.useForm();
  const [editForm] = Form.useForm();
  const [currentRecord, setCurrentRecord] = useState<any>(null);
  const theme = (localStorage.getItem('theme') as 'light' | 'dark') || 'light';

  const handleCreate = async (values: any) => {
    try {
      const res = await invokeWithEvent('device:create', values);
      if (res?.success) {
        message.success('新增设备成功');
        setCreateVisible(false);
        createForm.resetFields();
        actionRef.current?.reload();
      } else {
        message.error(res?.message || '新增设备失败');
      }
    } catch (error) {
      message.error('新增设备失败');
    }
  };

  const handleEdit = (record: any) => {
    setCurrentRecord(record);
    editForm.setFieldsValue({
      ...record,
    });
    setEditVisible(true);
  };

  const handleUpdate = async (values: any) => {
    try {
      const res = await invokeWithEvent('device:update', {
        id: currentRecord.id,
        ...values,
      });
      if (res?.success) {
        message.success('更新设备成功');
        setEditVisible(false);
        editForm.resetFields();
        setCurrentRecord(null);
        actionRef.current?.reload();
      } else {
        message.error(res?.message || '更新设备失败');
      }
    } catch (error) {
      message.error('更新设备失败');
    }
  };

  const handleDelete = (record: any) => {
    setCurrentRecord(record);
    setDeleteVisible(true);
  };

  const confirmDelete = async () => {
    try {
      const result = await invokeWithEvent('device:delete', currentRecord.id);
      if (result.success) {
        message.success('删除成功');
        setDeleteVisible(false);
        setCurrentRecord(null);
        actionRef.current?.reload();
      } else {
        message.error(result.message || '删除失败');
      }
    } catch (error) {
      message.error('删除失败');
    }
  };

  const fetchData = async (params: any) => {
    try {
      const { current, pageSize, ...restParams } = params;
      const filters: any = {};

      if (restParams.code) {
        filters.code = restParams.code;
      }
      if (restParams.name) {
        filters.name = restParams.name;
      }
      if (restParams.type) {
        filters.type = restParams.type;
      }
      if (restParams.brand) {
        filters.brand = restParams.brand;
      }
      if (restParams.status && restParams.status !== '') {
        filters.status = restParams.status;
      }

      const data = await invoke<any[]>('device:list', filters);
      const list = Array.isArray(data) ? data : [];

      return {
        data: list,
        success: true,
        total: list.length,
      };
    } catch (error) {
      return {
        data: [],
        success: false,
        total: 0,
      };
    }
  };

  const fetchUniqueValues = async (field: string) => {
    try {
      const data = await invoke<any[]>('device:list');
      const list = Array.isArray(data) ? data : [];
      return [...new Set(list.map((item) => item[field]).filter(Boolean))].map(
        (value) => ({ label: value, value }),
      );
    } catch {
      return [];
    }
  };

  const columns: ProColumns<any>[] = [
    {
      title: '设备编号',
      dataIndex: 'code',
      valueType: 'select',
      request: async () => fetchUniqueValues('code'),
      fieldProps: {
        placeholder: '请选择设备编号',
        showSearch: true,
        filterOption: (input: string, option: any) =>
          option.label.toLowerCase().includes(input.toLowerCase()),
      },
    },
    {
      title: '设备名称',
      dataIndex: 'name',
      hideInTable: true,
      valueType: 'select',
      request: async () => fetchUniqueValues('name'),
      fieldProps: {
        placeholder: '请选择设备名称',
        showSearch: true,
        filterOption: (input: string, option: any) =>
          option.label.toLowerCase().includes(input.toLowerCase()),
      },
    },
    {
      title: '设备类型',
      dataIndex: 'type',
      valueType: 'select',
      valueEnum: typeOptions.reduce((acc: any, item) => {
        acc[item.value] = { text: item.label };
        return acc;
      }, {}),
      fieldProps: {
        placeholder: '请选择设备类型',
      },
    },
    {
      title: '设备厂商',
      dataIndex: 'brand',
      valueType: 'select',
      request: async () => fetchUniqueValues('brand'),
      fieldProps: {
        placeholder: '请选择设备厂商',
        showSearch: true,
        filterOption: (input: string, option: any) =>
          option.label.toLowerCase().includes(input.toLowerCase()),
      },
    },
    {
      title: '规格型号',
      dataIndex: 'model',
      hideInSearch: true,
    },
    {
      title: '单价',
      dataIndex: 'price',
      hideInSearch: true,
      render: (text: any) => {
        if (typeof text === 'number') {
          return text.toLocaleString('zh-CN', {
            minimumFractionDigits: 2,
            maximumFractionDigits: 2,
          });
        }
        return text;
      },
    },
    {
      title: '存放地点',
      dataIndex: 'location',
      hideInSearch: true,
    },
    {
      title: '设备状态',
      dataIndex: 'status',
      valueType: 'select',
      request: async () => statusOptions,
      fieldProps: {
        placeholder: '请选择设备状态',
      },
      render: (status: string) => {
        const statusMap: any = {
          available: '可用',
          borrowed: '已借出',
          maintenance: '维修中',
          scrap: '已报废',
        };
        const displayStatus = statusMap[status] || status;

        let statusColor = '#52c41a';
        if (status === 'borrowed') statusColor = '#6366F1';
        if (status === 'maintenance') statusColor = '#faad14';
        if (status === 'scrap') statusColor = '#ff4d4f';

        return (
          <span style={{ color: statusColor, fontWeight: 500 }}>
            {displayStatus}
          </span>
        );
      },
    },
    {
      title: '操作',
      valueType: 'option',
      width: 120,
      fixed: 'right',
      render: (_: any, r: any) => [
        <Button type="link" key="r.edit" onClick={() => handleEdit(r)}>
          编辑
        </Button>,
        <Button
          type="link"
          danger
          key="r.delete"
          onClick={() => handleDelete(r)}
        >
          删除
        </Button>,
      ],
    },
  ];

  return (
    <>
      <GlobalSelectStyles $theme={theme} />
      <div style={{ padding: 24 }}>
        <ProTable<any>
          columns={columns}
          actionRef={actionRef}
          request={fetchData}
          rowKey="id"
          search={{
            labelWidth: 120,
          }}
          pagination={{
            pageSize: 10,
            showSizeChanger: true,
            showQuickJumper: true,
            showTotal: (total) => `共 ${total} 条记录`,
          }}
          scroll={{ x: 1000 }}
          headerTitle="设备管理"
          toolBarRender={() => [
            <Button
              type="primary"
              key="create"
              onClick={() => setCreateVisible(true)}
            >
              新增设备
            </Button>,
          ]}
        />
        <StyledModal
          $theme={theme}
          title="新增设备"
          open={createVisible}
          onCancel={() => {
            setCreateVisible(false);
            createForm.resetFields();
          }}
          onOk={() => createForm.submit()}
          destroyOnClose
          width={600}
        >
          <Form
            form={createForm}
            onFinish={handleCreate}
            labelCol={{ span: 6 }}
            wrapperCol={{ span: 18 }}
            layout="horizontal"
            style={{ marginTop: 16 }}
          >
            <Form.Item
              name="code"
              label="设备编号"
              rules={[{ required: true, message: '请输入设备编号' }]}
            >
              <Input placeholder="请输入设备编号" />
            </Form.Item>
            <Form.Item
              name="name"
              label="设备名称"
              rules={[{ required: true, message: '请输入设备名称' }]}
            >
              <Input placeholder="请输入设备名称" />
            </Form.Item>
            <Form.Item
              name="type"
              label="设备类型"
              rules={[{ required: true, message: '请选择设备类型' }]}
            >
              <Select placeholder="请选择设备类型" options={typeOptions} />
            </Form.Item>
            <Form.Item
              name="brand"
              label="设备厂商"
              rules={[{ required: true, message: '请输入设备厂商' }]}
            >
              <Input placeholder="请输入设备厂商" />
            </Form.Item>
            <Form.Item
              name="model"
              label="规格型号"
              rules={[{ required: true, message: '请输入规格型号' }]}
            >
              <Input placeholder="请输入规格型号" />
            </Form.Item>
            <Form.Item
              name="price"
              label="单价"
              rules={[{ required: true, message: '请输入单价' }]}
            >
              <InputNumber
                placeholder="请输入单价"
                style={{ width: '100%' }}
                min={0}
                step={0.01}
                formatter={(value) => `¥ ${value}`}
                parser={(value) => (value?.replace(/¥\s?/, '') || '') as any}
              />
            </Form.Item>
            <Form.Item
              name="location"
              label="存放地点"
              rules={[{ required: true, message: '请输入存放地点' }]}
            >
              <Input placeholder="请输入存放地点" />
            </Form.Item>
            <Form.Item name="status" label="设备状态" initialValue="available">
              <Select
                placeholder="请选择设备状态"
                options={statusOptions.filter((opt) => opt.value !== '')}
              />
            </Form.Item>
          </Form>
        </StyledModal>
        <StyledModal
          $theme={theme}
          title="编辑设备"
          open={editVisible}
          onCancel={() => {
            setEditVisible(false);
            editForm.resetFields();
            setCurrentRecord(null);
          }}
          onOk={() => editForm.submit()}
          destroyOnClose
          width={600}
        >
          <Form
            form={editForm}
            onFinish={handleUpdate}
            labelCol={{ span: 6 }}
            wrapperCol={{ span: 18 }}
            layout="horizontal"
            style={{ marginTop: 16 }}
          >
            <Form.Item name="code" label="设备编号">
              <Input disabled />
            </Form.Item>
            <Form.Item
              name="name"
              label="设备名称"
              rules={[{ required: true, message: '请输入设备名称' }]}
            >
              <Input placeholder="请输入设备名称" />
            </Form.Item>
            <Form.Item
              name="type"
              label="设备类型"
              rules={[{ required: true, message: '请选择设备类型' }]}
            >
              <Select placeholder="请选择设备类型" options={typeOptions} />
            </Form.Item>
            <Form.Item
              name="brand"
              label="设备厂商"
              rules={[{ required: true, message: '请输入设备厂商' }]}
            >
              <Input placeholder="请输入设备厂商" />
            </Form.Item>
            <Form.Item
              name="model"
              label="规格型号"
              rules={[{ required: true, message: '请输入规格型号' }]}
            >
              <Input placeholder="请输入规格型号" />
            </Form.Item>
            <Form.Item
              name="price"
              label="单价"
              rules={[{ required: true, message: '请输入单价' }]}
            >
              <InputNumber
                placeholder="请输入单价"
                style={{ width: '100%' }}
                min={0}
                step={0.01}
                formatter={(value) => `¥ ${value}`}
                parser={(value) => (value?.replace(/¥\s?/, '') || '') as any}
              />
            </Form.Item>
            <Form.Item
              name="location"
              label="存放地点"
              rules={[{ required: true, message: '请输入存放地点' }]}
            >
              <Input placeholder="请输入存放地点" />
            </Form.Item>
            <Form.Item name="status" label="设备状态">
              <Select
                placeholder="请选择设备状态"
                options={statusOptions.filter((opt) => opt.value !== '')}
              />
            </Form.Item>
          </Form>
        </StyledModal>
        <StyledModal
          $theme={theme}
          title="确认删除"
          open={deleteVisible}
          onOk={confirmDelete}
          onCancel={() => {
            setDeleteVisible(false);
            setCurrentRecord(null);
          }}
          okText="确认删除"
          cancelText="取消"
        >
          {currentRecord && (
            <div>
              <p>确认删除以下设备？</p>
              <p style={{ marginTop: 16 }}>
                <strong>设备编号：</strong>
                {currentRecord.code}
              </p>
              <p>
                <strong>设备名称：</strong>
                {currentRecord.name}
              </p>
              {currentRecord.status === 'borrowed' && (
                <p style={{ color: '#ff4d4f', marginTop: 16 }}>
                  该设备当前已借出，无法删除！
                </p>
              )}
              {currentRecord.status !== 'borrowed' && (
                <p style={{ color: '#ff4d4f', marginTop: 16 }}>
                  删除后数据不可恢复！
                </p>
              )}
            </div>
          )}
        </StyledModal>
      </div>
    </>
  );
}

