import { invoke, invokeWithEvent } from '@/services/ipc';
import { ProColumns, ProTable } from '@ant-design/pro-components';
import { Button, DatePicker, Form, Input, message, Modal, Select } from 'antd';
import dayjs from 'dayjs';
import { useEffect, useRef, useState } from 'react';
import styled, { createGlobalStyle } from 'styled-components';

const typeOptions = [
  { label: '柜式空调', value: '柜式空调' },
  { label: '数字示波器', value: '数字示波器' },
  { label: '笔记本电脑', value: '笔记本电脑' },
  { label: '服务器', value: '服务器' },
  { label: '打印机', value: '打印机' },
];

const GlobalSelectStyles = createGlobalStyle<{ $theme: 'light' | 'dark' }>`
  ${(props) =>
    props.$theme === 'dark'
      ? `
    .ant-select-dropdown {
      background: #2d3748 !important;
      border: 1px solid #4a5568 !important;
    }

    .ant-select-item {
      color: #ffffff !important;

      &:hover {
        background: #4a5568 !important;
      }

      &.ant-select-item-option-selected {
        background: #2d3748 !important;
        color: #667eea !important;
      }
    }

    .ant-select-item-option-active {
      background: #4a5568 !important;
    }
  `
      : ''}
`;

const GlobalDatePickerStyles = createGlobalStyle<{ $theme: 'light' | 'dark' }>`
  ${(props) =>
    props.$theme === 'dark'
      ? `
    .ant-picker-dropdown {
      background: #2d3748 !important;
      border: 1px solid #4a5568 !important;
    }

    .ant-picker-panel {
      background: #2d3748 !important;
      color: #ffffff !important;
    }

    .ant-picker-header {
      color: #ffffff !important;
      border-bottom-color: #4a5568 !important;
    }

    .ant-picker-footer {
      border-top-color: #4a5568 !important;
    }

    .ant-picker-cell {
      color: #ffffff !important;

      &:hover {
        background: #4a5568 !important;
      }

      &.ant-picker-cell-selected {
        background: #667eea !important;
      }

      &.ant-picker-cell-in-view {
        color: #ffffff !important;
      }

      &.ant-picker-cell-disabled {
        color: #718096 !important;
      }
    }

    .ant-picker-cell-inner {
      color: #ffffff !important;
    }

    .ant-picker-suffix {
      color: #ffffff !important;
    }

    .ant-picker-clear {
      color: #ffffff !important;
    }

    .ant-picker-separator {
      color: #ffffff !important;
    }

    .ant-picker-today-btn {
      color: #667eea !important;

      &:hover {
        color: #667eea !important;
      }
    }
  `
      : ''}
`;

const StyledModal = styled(Modal)<{ $theme: 'light' | 'dark' }>`
  .ant-modal-content {
    background: ${(props) =>
      props.$theme === 'light' ? '#ffffff' : '#1A202C'};
  }

  .ant-modal-header {
    background: ${(props) =>
      props.$theme === 'light' ? '#ffffff' : '#1A202C'};
    border-bottom: 1px solid
      ${(props) => (props.$theme === 'light' ? '#f0f0f0' : '#2d3748')};

    .ant-modal-title {
      color: ${(props) => (props.$theme === 'light' ? '#1A202C' : '#ffffff')};
    }
  }

  .ant-modal-close-x {
    color: ${(props) => (props.$theme === 'light' ? '#1A202C' : '#ffffff')};
  }

  .ant-modal-body {
    color: ${(props) => (props.$theme === 'light' ? '#1A202C' : '#ffffff')};
  }

  .ant-form-item-label > label {
    color: ${(props) => (props.$theme === 'light' ? '#1A202C' : '#ffffff')};
  }

  .ant-input,
  .ant-input-password {
    background: ${(props) =>
      props.$theme === 'light' ? '#ffffff' : '#2d3748'};
    border-color: ${(props) =>
      props.$theme === 'light' ? '#d9d9d9' : '#4a5568'};
    color: ${(props) => (props.$theme === 'light' ? '#1A202C' : '#ffffff')};

    &::placeholder {
      color: ${(props) => (props.$theme === 'light' ? '#bfbfbf' : '#718096')};
    }

    &:hover {
      border-color: ${(props) =>
        props.$theme === 'light' ? '#4096ff' : '#667eea'};
    }
  }

  .ant-input:focus,
  .ant-input-password:focus {
    border-color: ${(props) =>
      props.$theme === 'light' ? '#4096ff' : '#667eea'};
    box-shadow: ${(props) =>
      props.$theme === 'light'
        ? '0 0 0 2px rgba(64, 150, 255, 0.2)'
        : '0 0 0 2px rgba(102, 126, 234, 0.2)'};
  }

  .ant-select {
    .ant-select-selector {
      background: ${(props) =>
        props.$theme === 'light' ? '#ffffff' : '#2d3748'};
      border-color: ${(props) =>
        props.$theme === 'light' ? '#d9d9d9' : '#4a5568'};
      color: ${(props) => (props.$theme === 'light' ? '#1A202C' : '#ffffff')};

      .ant-select-selection-placeholder {
        color: ${(props) => (props.$theme === 'light' ? '#bfbfbf' : '#718096')};
      }

      .ant-select-selection-item {
        color: ${(props) => (props.$theme === 'light' ? '#1A202C' : '#ffffff')};
      }
    }

    &:hover .ant-select-selector {
      border-color: ${(props) =>
        props.$theme === 'light' ? '#4096ff' : '#667eea'};
    }

    &.ant-select-focused .ant-select-selector {
      border-color: ${(props) =>
        props.$theme === 'light' ? '#4096ff' : '#667eea'};
      box-shadow: ${(props) =>
        props.$theme === 'light'
          ? '0 0 0 2px rgba(64, 150, 255, 0.2)'
